package com.workbenchlens;

/** Static browser UI served by {@link WebApp}. */
final class WebPage {
    private WebPage() { }
    static final String HTML = """
            <!doctype html>
            <html lang="en">
            <head>
              <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
              <meta name="theme-color" content="#f3f1eb"><title>Workbench Lens — Tool intelligence</title>
              <style>
                :root{color-scheme:light;--ink:#17221d;--muted:#68736d;--line:#dce2dc;--paper:#f4f4ef;--card:#fff;--green:#245b45;--mint:#e8f2ec;--amber:#8d6115;--gold:#f6edda;--shadow:0 18px 60px #17221d0a}
                *{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,textarea{font:inherit}.shell{max-width:1440px;margin:auto;min-height:100vh;padding:0 48px}.topbar{height:78px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:12px;font-size:15px;font-weight:720;letter-spacing:-.02em}.mark{width:34px;height:34px;border-radius:10px;background:var(--green);display:grid;place-items:center;color:#fff}.mark svg{width:19px}.top-right{display:flex;gap:24px;align-items:center;color:var(--muted);font-size:13px}.connection{display:flex;align-items:center;gap:8px}.dot{width:8px;height:8px;background:#d09332;border-radius:50%}.hero{padding:54px 0 36px;max-width:760px}.eyebrow{display:flex;gap:9px;align-items:center;color:var(--green);font-weight:700;font-size:11px;text-transform:uppercase;letter-spacing:.12em}.eyebrow:before{content:"";width:23px;height:1px;background:var(--green)}h1{font-size:clamp(34px,4vw,50px);line-height:1.08;letter-spacing:-.055em;margin:15px 0 13px;font-weight:650}.hero p{color:var(--muted);margin:0;max-width:620px;font-size:16px}.workspace{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(300px,.82fr);gap:22px;padding-bottom:48px}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow)}.main-card{padding:24px}.card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.card-title{margin:0;font-size:18px;letter-spacing:-.025em}.card-desc{color:var(--muted);font-size:13px;margin:5px 0 0}.step{font-size:11px;font-weight:700;color:var(--muted);background:#f1f3f0;border-radius:99px;padding:5px 10px;white-space:nowrap}.upload{position:relative;border:1px dashed #b9c8bd;border-radius:13px;background:#f8faf7;min-height:215px;margin-top:22px;display:flex;justify-content:center;align-items:center;text-align:center;overflow:hidden;transition:.18s}.upload.drag{border-color:var(--green);background:var(--mint)}.upload input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer}.upload-inner{padding:24px;pointer-events:none}.upload-icon{width:42px;height:42px;border:1px solid var(--line);background:#fff;border-radius:12px;margin:0 auto 12px;display:grid;place-items:center;color:var(--green)}.upload-icon svg{width:20px}.upload-title{font-weight:650}.upload-sub{font-size:12px;color:var(--muted);margin-top:3px}.file-name{margin-top:8px;color:var(--green);font-weight:650;font-size:12px}.preview{display:none;max-width:100%;max-height:270px;object-fit:contain}.upload.has-image .upload-inner{display:none}.upload.has-image .preview{display:block}.upload.has-image input{cursor:pointer;background:#0000}.label{display:block;font-size:12px;font-weight:660;margin:20px 0 8px}.question{resize:vertical;min-height:94px;width:100%;padding:12px 14px;border:1px solid var(--line);border-radius:10px;outline:0;background:#fff;line-height:1.5}.question:focus,input:focus{border-color:#6b977f;box-shadow:0 0 0 3px #e8f2ec}.controls{display:grid;grid-template-columns:minmax(180px,1fr) auto;gap:12px;align-items:end;margin-top:19px}.password-wrap{position:relative}.password-wrap input{width:100%;height:43px;border:1px solid var(--line);border-radius:9px;padding:0 12px;outline:0}.connect-btn{height:43px;padding:0 15px;background:#f7f8f6;border:1px solid var(--line);border-radius:9px;font-weight:620;cursor:pointer;color:var(--ink)}.submit{height:46px;width:100%;margin-top:14px;border:0;border-radius:10px;background:var(--green);color:#fff;font-weight:650;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;transition:background .18s}.submit:hover{background:#194b36}.submit:disabled,.connect-btn:disabled{opacity:.55;cursor:wait}.submit svg{width:17px}.status{font-size:12px;color:var(--muted);min-height:20px;margin-top:8px}.status.error{color:#a53728}.results{display:none;margin-top:22px;border-top:1px solid var(--line);padding-top:20px}.results.visible{display:block}.result-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:13px}.result-heading h3{margin:0;font-size:16px}.badge{padding:4px 8px;border-radius:6px;font-size:10px;letter-spacing:.05em;font-weight:750;text-transform:uppercase}.badge.unverified{background:var(--gold);color:var(--amber)}.result-block{border:1px solid var(--line);border-radius:10px;padding:14px;margin-top:10px}.result-label{font-size:10px;font-weight:750;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);margin-bottom:6px}.result-text{font-size:13px;white-space:pre-wrap}.aside{display:flex;flex-direction:column;gap:16px}.side-card{padding:21px}.side-card h2{font-size:15px;margin:0;letter-spacing:-.015em}.side-card p{font-size:12px;color:var(--muted);margin:6px 0 0}.trust-row{display:flex;gap:11px;padding:14px 0;border-bottom:1px solid #edf0ec}.trust-row:last-child{border-bottom:0;padding-bottom:0}.trust-icon{width:29px;height:29px;flex:0 0 29px;border-radius:8px;display:grid;place-items:center;background:var(--mint);color:var(--green);font-size:13px;font-weight:750}.trust-row strong{display:block;font-size:12px}.trust-row span{display:block;color:var(--muted);font-size:11px;margin-top:2px}.trust-row.ai .trust-icon{background:var(--gold);color:var(--amber)}.catalogue{margin-top:13px}.tool{padding:11px 0;border-bottom:1px solid #edf0ec}.tool:last-child{border:0;padding-bottom:0}.tool-name{font-size:12px;font-weight:650}.tool-meta{display:flex;justify-content:space-between;gap:10px;color:var(--muted);font-size:11px;margin-top:2px}.empty{padding:18px 0 3px;font-size:12px;color:var(--muted)}.side-note{background:#eef3ef;border-color:#dce8df;box-shadow:none}.side-note p{line-height:1.65}.footer{border-top:1px solid var(--line);padding:17px 0 24px;display:flex;justify-content:space-between;gap:18px;color:var(--muted);font-size:11px}.spinner{width:15px;height:15px;border:2px solid #ffffff66;border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
                @media(max-width:860px){.shell{padding:0 24px}.workspace{grid-template-columns:minmax(0,1.35fr) minmax(260px,.8fr);gap:14px}.main-card{padding:19px}.side-card{padding:17px}.top-right{gap:12px}}
                @media(max-width:650px){.shell{padding:0 16px}.topbar{height:64px}.top-right .local-label{display:none}.hero{padding:38px 0 25px}.hero p{font-size:14px}.workspace{grid-template-columns:1fr}.main-card{padding:17px}.aside{display:grid;grid-template-columns:1fr 1fr;align-items:start}.side-note{grid-column:1/-1}.controls{grid-template-columns:1fr}.connect-btn{width:100%}.footer{flex-direction:column;gap:4px}}
              </style>
            </head>
            <body>
              <div class="shell">
                <header class="topbar"><div class="brand"><span class="mark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M14.5 6.5 17.5 9.5M4 20l3.5-.7L19 7.8a2.12 2.12 0 0 0-3-3L4.5 16.3 4 20Z"/><path d="m13 5 6 6M4 20h16"/></svg></span>Workbench Lens</div><div class="top-right"><span class="local-label">Private local workspace</span><span class="connection"><i class="dot" id="connectionDot"></i><span id="connectionLabel">Oracle not connected</span></span></div></header>
                <main><section class="hero"><div class="eyebrow">Your workshop, in focus</div><h1>Know your tools.<br>Work with confidence.</h1><p>Share a photo, ask a question, and explore your workshop catalogue with a little help from local AI.</p></section>
                  <section class="card main-card" id="authPanel" style="max-width:680px;margin-bottom:24px"><h2 class="card-title">Workbench Lens account</h2><p class="card-desc">Register or sign in. Your account password is separate from the Oracle catalogue password.</p><div style="display:flex;gap:10px;margin:16px 0"><button class="connect-btn" id="showLogin">Log in</button><button class="connect-btn" id="showRegister">Register</button></div><div id="authFields"><label class="label">Username or email</label><input id="authUsername" autocomplete="username" style="width:100%;height:43px;border:1px solid var(--line);border-radius:9px;padding:0 12px"><div id="emailWrap" hidden><label class="label">Email</label><input id="authEmail" type="email" autocomplete="email" style="width:100%;height:43px;border:1px solid var(--line);border-radius:9px;padding:0 12px"></div><label class="label">Account password</label><input id="authPassword" type="password" autocomplete="current-password" style="width:100%;height:43px;border:1px solid var(--line);border-radius:9px;padding:0 12px"><button class="connect-btn" id="authSubmit" style="margin-top:14px">Log in</button><div class="status" id="authStatus">Use your Workbench Lens account.</div></div><section id="adminPanel" hidden style="margin-top:20px"><h3>Registered users (admin only)</h3><div id="userList"></div></section></section>
                  <div id="appWorkspace" hidden>
                  <div class="workspace"><section class="card main-card"><div class="card-head"><div><h2 class="card-title">Ask about a tool</h2><p class="card-desc">Add a photo and tell us what you’d like to know.</p></div><span class="step">IMAGE + QUESTION</span></div>
                    <label class="upload" id="dropzone"><input id="imageInput" type="file" accept="image/png,image/jpeg,image/gif,image/webp"><div class="upload-inner"><div class="upload-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3" y="4" width="18" height="16" rx="3"/><circle cx="8.5" cy="9" r="1.5"/><path d="m21 15-5-5L5 20"/></svg></div><div class="upload-title">Drop a tool photo here, or browse</div><div class="upload-sub">PNG, JPG, GIF or WebP · up to 8 MB</div><div class="file-name" id="fileName"></div></div><img class="preview" id="preview" alt="Selected tool photo preview"></label>
                    <label class="label" for="question">What would you like to know?</label><textarea id="question" class="question" maxlength="4000" placeholder="For example: What is this tool typically used for, and what safety points should I keep in mind?"></textarea>
                    <div class="controls"><div><label class="label" for="password" style="margin-top:0">Oracle catalogue password</label><div class="password-wrap"><input id="password" type="password" autocomplete="current-password" placeholder="Used for this local session"></div></div><button class="connect-btn" id="connect">Connect catalogue</button></div>
                    <button class="submit" id="ask" disabled><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="m14 4 6 6m-3-9-9 9m0 0-4 8 8-4m-4-4 7 7"/></svg>Ask Workbench Lens</button><div class="status" id="status">Connect your catalogue to get started.</div>
                    <div class="results" id="results"><div class="result-heading"><h3>Workbench Lens response</h3><span class="badge unverified">AI response · unverified</span></div><div class="result-block"><div class="result-label">What the image may show</div><div class="result-text" id="description"></div></div><div class="result-block"><div class="result-label">Answer</div><div class="result-text" id="answer"></div></div></div>
                  </section><aside class="aside"><section class="card side-card"><h2>Know what’s verified</h2><p>AI suggestions and reviewed workshop information stay clearly distinct.</p><div class="trust-row ai"><div class="trust-icon">~</div><div><strong>AI image suggestions</strong><span>Always marked unverified until checked.</span></div></div><div class="trust-row"><div class="trust-icon">✓</div><div><strong>Reviewed catalogue</strong><span>Oracle entries show their saved review status.</span></div></div><div class="trust-row"><div class="trust-icon">i</div><div><strong>Safety first</strong><span>Use the maker’s manual for tool-specific directions.</span></div></div></section>
                    <section class="card side-card"><h2>Your workshop catalogue</h2><p id="catalogueCount">Connect Oracle to view its tools.</p><div class="catalogue" id="catalogue"><div class="empty">Your catalogue will appear here after connecting.</div></div></section>
                    <section class="card side-card side-note"><h2>Made to stay on your machine</h2><p>Your photo is sent to the local Ollama service. Oracle access is made from this app server; passwords are held only in the current server session.</p></section></aside></div>
                  </div></main><footer class="footer"><span>Workbench Lens · Local workshop companion</span><span>AI-generated information is a starting point, not a verified tool guide.</span></footer>
              </div>
              <script>
                const input=document.getElementById('imageInput'),drop=document.getElementById('dropzone'),preview=document.getElementById('preview'),statusEl=document.getElementById('status'),askBtn=document.getElementById('ask'),connectBtn=document.getElementById('connect');let imageData='',connected=false;
                let authMode='login',account=null;const authStatus=document.getElementById('authStatus');
                document.getElementById('showLogin').onclick=()=>{authMode='login';document.getElementById('emailWrap').hidden=true;document.getElementById('authSubmit').textContent='Log in';document.getElementById('authPassword').autocomplete='current-password'};
                document.getElementById('showRegister').onclick=()=>{authMode='register';document.getElementById('emailWrap').hidden=false;document.getElementById('authSubmit').textContent='Create account';document.getElementById('authPassword').autocomplete='new-password'};
                document.getElementById('authSubmit').onclick=async()=>{const username=document.getElementById('authUsername').value.trim(),password=document.getElementById('authPassword').value;authStatus.textContent='Working…';try{const payload={username,password};if(authMode==='register')payload.email=document.getElementById('authEmail').value.trim();const r=await fetch('/api/'+(authMode==='register'?'register':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.error);account=d;document.getElementById('authPassword').value='';document.getElementById('appWorkspace').hidden=false;authStatus.textContent='Signed in as '+d.username+' ('+d.role+'). Now connect the Oracle catalogue below.';document.getElementById('authUsername').disabled=true;document.getElementById('authPassword').disabled=true;document.getElementById('authSubmit').hidden=true;if(d.role==='ADMIN'){const p=document.getElementById('adminPanel');p.hidden=false;const u=await fetch('/api/admin/users');const ud=await u.json();if(u.ok)document.getElementById('userList').textContent=ud.users.map(x=>x.username+' · '+x.email+' · '+x.role).join('\\n')} }catch(e){authStatus.textContent=e.message}};
                function setStatus(message,error=false){statusEl.textContent=message;statusEl.className='status'+(error?' error':'')}
                function fileSelected(file){if(!file)return;if(!['image/png','image/jpeg','image/gif','image/webp'].includes(file.type)||file.size>8*1024*1024){setStatus('Choose a PNG, JPEG, GIF or WebP image up to 8 MB.',true);return}const reader=new FileReader();reader.onload=()=>{imageData=String(reader.result).split(',')[1];preview.src=reader.result;drop.classList.add('has-image');document.getElementById('fileName').textContent=file.name;askBtn.disabled=!connected};reader.readAsDataURL(file)}
                input.addEventListener('change',()=>fileSelected(input.files[0]));for(const event of ['dragenter','dragover'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.add('drag')});for(const event of ['dragleave','drop'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.remove('drag')});drop.addEventListener('drop',e=>fileSelected(e.dataTransfer.files[0]));
                function renderTools(tools){const host=document.getElementById('catalogue');host.replaceChildren();document.getElementById('catalogueCount').textContent=tools.length+' '+(tools.length===1?'tool':'tools')+' in Oracle';if(!tools.length){host.innerHTML='<div class="empty">No tools in the catalogue yet.</div>';return}for(const t of tools){const row=document.createElement('div');row.className='tool';const name=document.createElement('div');name.className='tool-name';name.textContent=t.name;const meta=document.createElement('div');meta.className='tool-meta';const category=document.createElement('span');category.textContent=(t.group||'Unassigned')+' · '+t.category;const state=document.createElement('span');state.textContent=t.status||'UNVERIFIED';meta.append(category,state);row.append(name,meta);if(t.purpose){const purpose=document.createElement('div');purpose.className='tool-detail';purpose.textContent='Purpose: '+t.purpose;row.append(purpose)}if(t.safetyNotes){const safety=document.createElement('div');safety.className='tool-detail';safety.textContent='Safety: '+t.safetyNotes;row.append(safety)}host.append(row)}}
                connectBtn.addEventListener('click',async()=>{const password=document.getElementById('password').value;if(!password){setStatus('Enter your Oracle password to connect.',true);return}connectBtn.disabled=true;setStatus('Connecting to the Oracle catalogue…');try{const response=await fetch('/api/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Connection failed.');connected=true;document.getElementById('password').value='';document.getElementById('connectionDot').style.background='#438b5c';document.getElementById('connectionLabel').textContent='Oracle connected';connectBtn.textContent='Connected';askBtn.disabled=!imageData;renderTools(data.tools);setStatus('Catalogue connected. Add a photo and a question when you’re ready.')}catch(e){connected=false;setStatus(e.message,true)}finally{connectBtn.disabled=false}});
                askBtn.addEventListener('click',async()=>{const question=document.getElementById('question').value.trim();if(!imageData){setStatus('Add a tool photo first.',true);return}if(!question){setStatus('Write a question about the tool first.',true);return}askBtn.disabled=true;askBtn.innerHTML='<span class="spinner"></span> Looking closely…';setStatus('Asking your local AI. This may take a moment.');document.getElementById('results').classList.remove('visible');try{const response=await fetch('/api/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,image:imageData})});const data=await response.json();if(!response.ok)throw new Error(data.error||'The request could not be completed.');document.getElementById('description').textContent=data.description;document.getElementById('answer').textContent=data.answer;document.getElementById('results').classList.add('visible');renderTools(data.catalogue);setStatus('Response ready. AI-generated information is unverified; check it against trusted sources.')}catch(e){setStatus(e.message,true)}finally{askBtn.disabled=!connected;askBtn.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="m14 4 6 6m-3-9-9 9m0 0-4 8 8-4m-4-4 7 7"/></svg>Ask Workbench Lens'}});
              </script>
            </body></html>
            """;
}
